import urllib.request
import re

# Try different dataset prefixes
prefixes = ['px-x-0104010000', 'px-x-0104020000', 'px-x-0104030000', 'px-x-0105010000']
for prefix in prefixes:
    for i in range(1, 20):
        code = f'{prefix}_{i}'
        url = f'https://www.pxweb.bfs.admin.ch/pxweb/en/{code}/'
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        try:
            with urllib.request.urlopen(req, timeout=3) as response:
                data = response.read().decode('utf-8')[:2000]
                if 'error' not in data.lower()[:500]:
                    descriptions = re.findall(r'tableofcontent_link[^>]*>(.*?)<', data)
                    for d in descriptions:
                        print(f'{code}: {d[:100]}')
        except:
            pass
